import type { Cv } from '@/schema/cv'
import type { RichText } from '@/schema/richText'
import {
  CHEVRON_HEIGHT,
  CHEVRON_WIDTH,
  chevronSvg,
} from '@/pdf/chevron'
import {
  certificationLine,
  contactLines,
  experienceEntries,
  expertiseLines,
  fullName,
  hasSecondPageContent,
  languageLine,
  presentSections,
  renderableRichText,
  projectEntries,
  qualificationLine,
} from '@/pdf/model'

/**
 * Pixel-matched recreation of the "Avery Quinn - short CV" PowerPoint template.
 * The original file is 10 x 6.25 in (16:10), not 12.8 x 8 in.
 *
 * Static master graphics are embedded directly in this file so the generated
 * presentation does not depend on additional template assets.
 */

const SLIDE_WIDTH = 10
const SLIDE_HEIGHT = 6.25

/**
 * Static branding, not CV data: the deck's company metadata and the header logo.
 * Change these together with src/pdf/assets/brand-logo.png to rebrand the template.
 */
const BRAND_NAME = 'Brand'
const BRAND_LAYOUT = 'BRAND_CV_16_10'

/**
 * Coordinates below are literal template positions, in inches, as elsewhere in this
 * file. Two conventions worth knowing when editing them:
 *
 * - Body text sits 0.158in right of its section bar. That is the left padding, and it
 *   lives in the text box's own x: pptxgenjs's `margin` is in *points*, so the
 *   `[0.05, 0.1, 0.05, 0.1]` values throughout are effectively zero.
 * - Contact text starts 0.06in past the right edge of its icon, or the icon overlaps
 *   the first characters.
 *
 * Widths were reduced by the same amount the x moved, so every right edge is
 * unchanged from the original template.
 */

const TEMPLATE_MASTER_BG = 'data:image/png;base64,'
// The same file the PDF header uses (src/pdf/assets/brand-logo.png),
// inlined so the generated deck needs no external asset.
const BRAND_LOGO = 'data:image/png;base64,'
const EMAIL_ICON = 'data:image/svg+xml;base64,'
const LOCATION_ICON = 'data:image/svg+xml;base64,'

const C = {
  header: '0F9CD8',
  dark: '1F497D',
  blue: '4F81BD',
  white: 'FFFFFF',
  card: 'F2F2F2', // bg1 @ 95% luminance in the source template
  black: '000000',
  divider: '7F7F7F',
} as const

type Slide = any

const imageUrlToDataUrl = async (url: string): Promise<string> => {
  if (url.startsWith('data:')) return url
  const response = await fetch(url)
  if (!response.ok) throw new Error(`Unable to load image: ${url}`)
  const blob = await response.blob()
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onloadend = () => resolve(String(reader.result))
    reader.onerror = reject
    reader.readAsDataURL(blob)
  })
}

const makeCircularDataUrl = async (dataUrl: string, sizeInches: number): Promise<string> => {
  const DPI = 220
  const size = Math.max(1, Math.round(sizeInches * DPI))
  const img = new Image()
  img.crossOrigin = 'anonymous'
  img.src = dataUrl
  await new Promise<void>((resolve, reject) => {
    img.onload = () => resolve()
    img.onerror = () => reject(new Error('Failed to load profile image'))
  })

  const canvas = document.createElement('canvas')
  canvas.width = size
  canvas.height = size
  const ctx = canvas.getContext('2d')
  if (!ctx) throw new Error('Canvas is not available')

  ctx.save()
  ctx.beginPath()
  ctx.arc(size / 2, size / 2, size / 2, 0, Math.PI * 2)
  ctx.clip()

  const scale = Math.max(size / img.width, size / img.height)
  const dw = img.width * scale
  const dh = img.height * scale
  ctx.drawImage(img, (size - dw) / 2, (size - dh) / 2, dw, dh)
  ctx.restore()

  return canvas.toDataURL('image/png')
}

const addMasterBackground = (slide: Slide) => {
  slide.addImage({
    data: TEMPLATE_MASTER_BG,
    x: 0,
    y: 0,
    w: SLIDE_WIDTH,
    h: SLIDE_HEIGHT,
  })
}

const addCard = (slide: Slide, x: number, y: number, w: number, h: number) => {
  // The source template uses PowerPoint's "Rectangle: Single Corner Rounded"
  // (round1Rect) with only the upper-right corner rounded.
  slide.addShape('round1Rect' as any, {
    x, y, w, h,
    fill: { color: C.card },
    line: { color: C.card, transparency: 100 },
    radius: 0.11205,
  })
}

const addDivider = (slide: Slide, x: number, y: number, w: number, h: number) => {
  slide.addShape('line', {
    x, y, w, h,
    line: { color: C.divider, width: 0.5, dashType: 'dash' },
  })
}

const addSectionBar = (
  slide: Slide,
  title: string,
  x: number,
  y: number,
  w: number,
  variant: 'dark' | 'blue',
  options: {
    lineX: number
    lineY: number
    lineW: number
    prefixSpaces?: number
  },
) => {
  const fill = variant === 'dark' ? C.dark : C.blue
  slide.addShape('rect', {
    x, y, w, h: 0.3,
    fill: { color: fill },
    line: { color: fill, transparency: 100 },
  })

  // In the source PPTX the title is centered inside the *whole* bar.
  // The leading spaces are intentional: they reserve visual room for the
  // white marker line exactly like the original template text does.
  slide.addText(`${' '.repeat(options.prefixSpaces ?? 0)}${title}`, {
    x,
    y,
    w,
    h: 0.3,
    fontFace: 'Arial',
    fontSize: 10,
    italic: true,
    color: C.white,
    margin: [0.05, 0.1, 0.05, 0.1],
    valign: 'mid',
    align: 'center',
    fit: 'shrink',
  })

  slide.addShape('line', {
    x: options.lineX,
    y: options.lineY,
    w: options.lineW,
    h: 0,
    line: { color: C.white, width: 2 },
  })
}

/** Template position of the header logo. The chevrons align against this. */
const LOGO_BOX = { x: 8.864, y: 0.254, w: 1.011, h: 0.514 } as const

/** Horizontal gap between the chevrons and the logo. */
const CHEVRON_LOGO_GAP = 0.15

/**
 * The PDF's chevrons, rendered from the shared geometry as an SVG image. pptxgenjs
 * has no arbitrary-polygon shape, and the previous rotated `halfFrame` was only an
 * approximation that could drift from the PDF.
 */
const addHeaderChevrons = (slide: Slide) => {
  const svg = `data:image/svg+xml;base64,${btoa(chevronSvg())}`
  const height = 0.675
  const width = (height * CHEVRON_WIDTH) / CHEVRON_HEIGHT

  slide.addImage({
    data: svg,
    // Centred on the logo rather than on the header band, and derived from LOGO_BOX
    // so moving the logo carries the chevrons with it.
    x: LOGO_BOX.x - CHEVRON_LOGO_GAP - width,
    y: LOGO_BOX.y + (LOGO_BOX.h - height) / 2,
    w: width,
    h: height,
  })
}

const addHeader = async (slide: Slide, cv: Cv) => {
  slide.addShape('rect', {
    x: 0,
    y: -0.001,
    w: 10,
    h: 1.519,
    fill: { color: C.header },
    line: { color: C.header, transparency: 100 },
  })

  if (cv.personal.photo?.trim()) {
    try {
      const raw = await imageUrlToDataUrl(cv.personal.photo)
      const circ = await makeCircularDataUrl(raw, 1.357)
      slide.addImage({ data: circ, x: 0.266, y: 0.051, w: 1.357, h: 1.357 })
      slide.addShape('ellipse', {
        x: 0.266,
        y: 0.051,
        w: 1.357,
        h: 1.357,
        fill: { color: C.white, transparency: 100 },
        line: { color: C.white, width: 3 },
      })
    } catch (error) {
      console.warn('Profile photo could not be rendered:', error)
    }
  }

  const name = fullName(cv)
  if (name) {
    slide.addShape('roundRect', {
      x: 1.803,
      y: 0.495,
      w: 3.258,
      h: 0.339,
      rectRadius: 0.16,
      fill: { color: C.white },
      line: { color: C.white, transparency: 100 },
    })
    slide.addText(name, {
      x: 1.803,
      y: 0.495,
      w: 3.258,
      h: 0.339,
      fontFace: 'Calibri',
      fontSize: 15,
      bold: true,
      color: C.black,
      align: 'center',
      valign: 'mid',
      margin: [0.05, 0.1, 0.05, 0.1],
      fit: 'shrink',
    })
  }

  if (cv.personal.headline?.trim()) {
    slide.addText(cv.personal.headline.trim(), {
      x: 2.499,
      y: 0.912,
      w: 1.864,
      h: 0.328,
      fontFace: 'Calibri',
      fontSize: 13.5,
      color: C.white,
      align: 'center',
      margin: [0.05, 0.1, 0.05, 0.1],
      fit: 'shrink',
    })
  }

  addHeaderChevrons(slide)

  slide.addImage({
    data: BRAND_LOGO,
    x: LOGO_BOX.x,
    y: LOGO_BOX.y,
    w: LOGO_BOX.w,
    h: LOGO_BOX.h,
  })

  const contacts = contactLines(cv).filter(Boolean)
  if (contacts[0]) {
    slide.addImage({ data: EMAIL_ICON, x: 5.959, y: 1.18, w: 0.323, h: 0.323 })
    slide.addText(contacts[0], {
      x: 6.342,
      y: 1.207,
      w: 1.901,
      h: 0.269,
      fontFace: 'Calibri',
      fontSize: 11,
      color: C.white,
      margin: [0.05, 0.1, 0.05, 0.1],
      fit: 'shrink',
    })
  }
  if (contacts[1]) {
    slide.addImage({ data: LOCATION_ICON, x: 8.303, y: 1.164, w: 0.323, h: 0.323 })
    slide.addText(contacts[1], {
      x: 8.686,
      y: 1.207,
      w: 1.314,
      h: 0.269,
      fontFace: 'Calibri',
      fontSize: 11,
      color: C.white,
      margin: [0.05, 0.1, 0.05, 0.1],
      fit: 'shrink',
    })
  }
}

const bulletRuns = (lines: string[], indent = 13.5): any[] =>
  lines.filter(Boolean).map((line, index, all) => ({
    text: line,
    options: {
      bullet: { indent },
      breakLine: index < all.length - 1,
    },
  }))

/**
 * Rich text as pptx runs. Marks map onto pptxgenjs's own run options, so the deck
 * keeps live formatting rather than flattened text; only the last run of a block
 * breaks the line.
 */
const richTextRuns = (
  value: RichText,
  options: { indent?: number; fontSize?: number } = {},
): any[] => {
  const { indent = 13.5, fontSize } = options
  const blocks = renderableRichText(value).blocks

  return blocks.flatMap((block, blockIndex) => {
    const lastBlock = blockIndex === blocks.length - 1

    return block.runs.map((run, runIndex) => ({
      text: run.text,
      options: {
        ...(fontSize === undefined ? {} : { fontSize }),
        ...(run.bold ? { bold: true } : {}),
        ...(run.italic ? { italic: true } : {}),
        ...(run.underline ? { underline: { style: 'sng' } } : {}),
        ...(block.type === 'bullet' ? { bullet: { indent } } : {}),
        breakLine: runIndex === block.runs.length - 1 && !lastBlock,
      },
    }))
  })
}

const addProfile = (slide: Slide, cv: Cv) => {
  addSectionBar(slide, 'Profile summary', 0.257, 1.626, 2.649, 'dark', {
    lineX: 0.347,
    lineY: 1.776,
    lineW: 0.625,
    prefixSpaces: 3,
  })
  slide.addText(richTextRuns(cv.profile.summary, { indent: 13.5 }), {
    x: 0.415,
    y: 1.973,
    w: 3.723,
    h: 1.447,
    fontFace: 'Arial',
    fontSize: 8,
    color: C.black,
    margin: [0.05, 0.1, 0.05, 0.1],
    fit: 'shrink',
    valign: 'top',
    paraSpaceBefore: 0,
    paraSpaceAfter: 0,
  })
}

const addQualifications = (slide: Slide, cv: Cv) => {
  addDivider(slide, 0.275, 3.453, 3.816, 0)
  addSectionBar(slide, 'Qualifications', 0.267, 3.635, 2.649, 'blue', {
    lineX: 0.347,
    lineY: 3.795,
    lineW: 0.625,
    prefixSpaces: 0,
  })
  slide.addText(bulletRuns(cv.qualifications.map(qualificationLine), 13.5), {
    x: 0.425,
    y: 3.982,
    w: 3.713,
    h: 0.675,
    fontFace: 'Arial',
    fontSize: 8,
    color: C.black,
    margin: 0.07,
    fit: 'shrink',
    valign: 'top',
    paraSpaceBefore: 0,
    paraSpaceAfter: 0,
  })
}

const addExpertise = (slide: Slide, cv: Cv) => {
  addDivider(slide, 0.266, 4.655, 3.816, 0)
  addSectionBar(slide, 'Areas of expertise', 0.275, 4.815, 2.649, 'dark', {
    lineX: 0.347,
    lineY: 4.965,
    lineW: 0.625,
    prefixSpaces: 3,
  })

  // One line per catalog group, matching the PDF: "Java: Spring (Expert, 5y 6m,
  // Within last month); Maven (Proficient)". Certification links follow on their own
  // lines, as clickable hyperlinks since PowerPoint supports them.
  const lines = expertiseLines(cv)
  const runs: any[] = []
  lines.forEach((line, lineIndex) => {
    const lastLine = lineIndex === lines.length - 1

    runs.push({
      text: `${line.label}: `,
      options: { bold: true, bullet: { indent: 13.5 } },
    })
    runs.push({
      text: line.value,
      options: { breakLine: line.links.length > 0 || !lastLine },
    })

    line.links.forEach((link, linkIndex) => {
      const lastLink = linkIndex === line.links.length - 1
      runs.push({
        text: link,
        options: {
          color: C.header,
          hyperlink: { url: link },
          breakLine: !(lastLine && lastLink),
        },
      })
    })
  })

  slide.addText(runs, {
    x: 0.433,
    y: 5.239,
    w: 3.723,
    h: 0.774,
    fontFace: 'Arial',
    fontSize: 8,
    color: C.black,
    margin: [0.05, 0.1, 0.05, 0.1],
    fit: 'shrink',
    valign: 'top',
    paraSpaceBefore: 0,
    paraSpaceAfter: 0,
  })
}

const addExperience = (slide: Slide, cv: Cv) => {
  addSectionBar(slide, 'Experience summary', 4.166, 1.626, 2.487, 'blue', {
    lineX: 4.275,
    lineY: 1.768,
    lineW: 0.4,
    prefixSpaces: 3,
  })
  addDivider(slide, 4.158, 1.785, 0, 4.221)

  const entries = experienceEntries(cv.experience)
  const runs: any[] = []

  // The source textbox begins with one empty paragraph before the first role.
  runs.push({ text: ' ', options: { breakLine: true, fontSize: 8 } })

  entries.forEach((entry, entryIndex) => {
    const title = [entry.title, entry.meta].filter(Boolean).join(' – ')
    runs.push({
      text: title,
      options: {
        fontSize: 9,
        bold: true,
        underline: { color: C.black },
        breakLine: true,
      },
    })
    runs.push({ text: ' ', options: { breakLine: true, fontSize: 8 } })

    runs.push(
      ...richTextRuns(entry.achievements, { indent: 9, fontSize: 8 }).map((run) => ({
        ...run,
        options: { ...run.options, breakLine: true },
      })),
    )

    const details = [...(entry.tech ? [entry.tech] : [])].filter(Boolean)
    details.forEach((detail) => {
      runs.push({
        text: detail,
        options: {
          fontSize: 8,
          bullet: { indent: 9 },
          breakLine: true,
        },
      })
    })

    if (entryIndex < entries.length - 1) {
      runs.push({ text: ' ', options: { breakLine: true, fontSize: 8 } })
      runs.push({ text: ' ', options: { breakLine: true, fontSize: 8 } })
    }
  })

  slide.addText(runs, {
    x: 4.324,
    y: 1.885,
    w: 5.371,
    h: 3.299,
    fontFace: 'Arial',
    fontSize: 8,
    color: C.black,
    margin: [0.05, 0.1, 0.05, 0.1],
    fit: 'shrink',
    valign: 'top',
    paraSpaceBefore: 0,
    paraSpaceAfter: 0,
  })
}

const addCertifications = (slide: Slide, cv: Cv) => {
  addSectionBar(slide, 'Certifications & Trainings', 0.257, 0.4, 2.649, 'dark', {
    lineX: 0.347,
    lineY: 0.55,
    lineW: 0.625,
    prefixSpaces: 16,
  })

  const items = cv.certifications.map(certificationLine).filter(Boolean)
  const runs: any[] = [
    {
      text: 'Certifications',
      options: {
        fontSize: 9,
        bold: true,
        underline: { color: C.black },
        breakLine: true,
      },
    },
    { text: ' ', options: { breakLine: true, fontSize: 8 } },
  ]
  items.forEach((item, index) => {
    runs.push({
      text: item,
      options: {
        bullet: { indent: 13.5 },
        breakLine: index < items.length - 1,
      },
    })
  })

  slide.addText(runs, {
    x: 0.415,
    y: 0.78,
    w: 3.742,
    h: 1.666,
    fontFace: 'Arial',
    fontSize: 8,
    color: C.black,
    margin: [0.05, 0.1, 0.05, 0.1],
    fit: 'shrink',
    valign: 'top',
  })
}

const addLanguagesAndSkills = (slide: Slide, cv: Cv) => {
  addSectionBar(slide, 'Languages & Soft Skills', 4.153, 0.4, 2.649, 'blue', {
    lineX: 4.219,
    lineY: 0.548,
    lineW: 0.625,
    prefixSpaces: 16,
  })
  addDivider(slide, 4.158, 0.559, 0.009, 2.426)

  const languages = cv.languages.map((entry) => languageLine(entry.name, entry.level)).filter(Boolean)
  const softSkills = cv.softSkills.map((entry) => entry.name.trim()).filter(Boolean)
  const runs: any[] = [
    {
      text: 'Languages',
      options: {
        fontSize: 9,
        bold: true,
        underline: { color: C.black },
        breakLine: true,
      },
    },
    { text: ' ', options: { breakLine: true, fontSize: 8 } },
  ]

  languages.forEach((language) => {
    runs.push({
      text: language,
      options: { bullet: { indent: 13.5 }, breakLine: true },
    })
  })

  runs.push({ text: ' ', options: { breakLine: true, fontSize: 8 } })
  runs.push({
    text: 'Soft Skills',
    options: {
      fontSize: 9,
      bold: true,
      underline: { color: C.black },
      breakLine: true,
    },
  })
  runs.push({ text: ' ', options: { breakLine: true, fontSize: 8 } })
  if (softSkills.length) {
    runs.push({ text: softSkills.join(', '), options: { bullet: { indent: 13.5 } } })
  }

  slide.addText(runs, {
    x: 4.311,
    y: 0.734,
    w: 3.723,
    h: 2.118,
    fontFace: 'Arial',
    fontSize: 8,
    color: C.black,
    margin: 0.07,
    fit: 'shrink',
    valign: 'top',
  })
}

const addProjects = (slide: Slide, cv: Cv, hasTopColumns: boolean) => {
  const yLine = hasTopColumns ? 3.07 : 0.82
  const yBar = hasTopColumns ? 3.175 : 0.4
  addDivider(slide, 0.257, yLine, 9.438, 0)
  addSectionBar(slide, 'Personal Projects', 0.257, yBar, 2.487, 'blue', {
    lineX: 0.331,
    lineY: hasTopColumns ? 3.326 : yBar + 0.151,
    lineW: 0.625,
    prefixSpaces: 9,
  })

  const projects = projectEntries(cv.projects)
  const runs: any[] = []
  projects.forEach((project, index) => {
    const meta = project.meta ? ` — ${project.meta}` : ''
    runs.push({
      text: `${project.title}${meta}`,
      options: {
        bold: true,
        bullet: { indent: 13.5 },
        breakLine: true,
      },
    })
    const description = [project.description, project.tech].filter(Boolean).join(' ')
    if (description) {
      runs.push({ text: description, options: { breakLine: index < projects.length - 1 } })
    }
    if (index < projects.length - 1) {
      runs.push({ text: ' ', options: { breakLine: true } })
    }
  })

  slide.addText(runs, {
    x: 0.415,
    y: hasTopColumns ? 3.55 : 0.775,
    w: 9.262,
    h: hasTopColumns ? 2.12 : 4.96,
    fontFace: 'Arial',
    fontSize: 8,
    color: C.black,
    margin: [0.05, 0.1, 0.05, 0.1],
    fit: 'shrink',
    valign: 'top',
  })
}

export const pptxFileName = (cv: Cv): string => {
  const slug = fullName(cv)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')

  return slug ? `${slug}-short-cv.pptx` : 'short-cv.pptx'
}

/**
 * Assembles the presentation without writing it, so tests can render it under node
 * via `pptx.write(...)`. Only the profile photo path needs browser APIs (canvas and
 * fetch), and that is skipped when no photo is set.
 */
export const buildPptx = async (cv: Cv) => {
  const module = await import('pptxgenjs')
  const PptxGenJS = module.default
  const pptx = new PptxGenJS()

  pptx.defineLayout({ name: BRAND_LAYOUT, width: SLIDE_WIDTH, height: SLIDE_HEIGHT })
  pptx.layout = BRAND_LAYOUT
  pptx.author = fullName(cv) || 'CV Builder'
  pptx.subject = 'CV export'
  pptx.title = fullName(cv) ? `${fullName(cv)} - short CV` : 'Short CV'
  pptx.company = BRAND_NAME
  // pptxgenjs exposes no document language setting: PptxGenJS has no `lang`
  // property and ThemeProps carries only the two font faces.
  pptx.theme = {
    headFontFace: 'Calibri',
    bodyFontFace: 'Arial',
  }

  const present = presentSections(cv)
  const firstPage = pptx.addSlide()
  addMasterBackground(firstPage)
  await addHeader(firstPage, cv)
  addCard(firstPage, 0.266, 1.754, 9.533, 4.445)

  if (present.profile) addProfile(firstPage, cv)
  if (present.qualifications) addQualifications(firstPage, cv)
  if (present.expertise) addExpertise(firstPage, cv)
  if (present.experience) addExperience(firstPage, cv)

  if (hasSecondPageContent(cv)) {
    const secondPage = pptx.addSlide()
    addMasterBackground(secondPage)
    addCard(secondPage, 0.266, 0.528, 9.533, 5.594)

    const hasTopColumns = present.certifications || present.languages || present.softSkills
    if (present.certifications) addCertifications(secondPage, cv)
    if (present.languages || present.softSkills) addLanguagesAndSkills(secondPage, cv)
    if (present.projects) addProjects(secondPage, cv, hasTopColumns)
  }

  return pptx
}

export const downloadPptx = async (cv: Cv): Promise<void> => {
  try {
    const pptx = await buildPptx(cv)
    await pptx.writeFile({ fileName: pptxFileName(cv) })
  } catch (error: unknown) {
    console.error('downloadPptx error:', error)
    throw new Error(error instanceof Error ? error.message : 'The PPTX could not be generated.')
  }
}

export default downloadPptx
